// API Jinx UI указан по памяти: Stepper/Step, Card, Stack, Input, Text, Button.
// Если имена или пропсы в вашей версии @jinx-ui/react отличаются — поправьте импорт и пропсы компонентов.
import { useState, type ChangeEvent, type FormEvent } from 'react';
import { Button, Card, Input, Stack, Step, Stepper, Text } from '@jinx-ui/react';

export interface RegistrationValues {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
}

export interface RegistrationFormProps {
  onSubmit: (values: RegistrationValues) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'];

const EMPTY_VALUES: RegistrationValues = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const SUMMARY_FIELDS: Array<{ key: keyof RegistrationValues; label: string }> = [
  { key: 'fullName', label: 'Имя' },
  { key: 'email', label: 'Email' },
  { key: 'phone', label: 'Телефон' },
  { key: 'country', label: 'Страна' },
  { key: 'city', label: 'Город' },
  { key: 'street', label: 'Улица, дом' },
  { key: 'zip', label: 'Индекс' },
];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY_VALUES);

  const isFirst = step === 0;
  const isLast = step === STEPS.length - 1;

  const handleChange =
    (field: keyof RegistrationValues) => (event: ChangeEvent<HTMLInputElement>) => {
      const { value } = event.target;
      setValues((prev) => ({ ...prev, [field]: value }));
    };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLast) {
      onSubmit(values);
      return;
    }
    setStep((prev) => prev + 1);
  };

  return (
    <Card>
      <form onSubmit={handleSubmit}>
        <Stack direction="column" gap="var(--jx-space-6)">
          <Stepper activeStep={step}>
            {STEPS.map((label, index) => (
              <Step key={label} index={index} label={label} />
            ))}
          </Stepper>

          {step === 0 && (
            <Stack direction="column" gap="var(--jx-space-4)">
              <Input
                label="Имя и фамилия"
                name="fullName"
                value={values.fullName}
                onChange={handleChange('fullName')}
                autoComplete="name"
              />
              <Input
                label="Email"
                name="email"
                type="email"
                value={values.email}
                onChange={handleChange('email')}
                autoComplete="email"
              />
              <Input
                label="Телефон"
                name="phone"
                type="tel"
                value={values.phone}
                onChange={handleChange('phone')}
                autoComplete="tel"
              />
            </Stack>
          )}

          {step === 1 && (
            <Stack direction="column" gap="var(--jx-space-4)">
              <Input
                label="Страна"
                name="country"
                value={values.country}
                onChange={handleChange('country')}
                autoComplete="country-name"
              />
              <Input
                label="Город"
                name="city"
                value={values.city}
                onChange={handleChange('city')}
                autoComplete="address-level2"
              />
              <Input
                label="Улица, дом"
                name="street"
                value={values.street}
                onChange={handleChange('street')}
                autoComplete="street-address"
              />
              <Input
                label="Индекс"
                name="zip"
                value={values.zip}
                onChange={handleChange('zip')}
                autoComplete="postal-code"
              />
            </Stack>
          )}

          {step === 2 && (
            <Stack direction="column" gap="var(--jx-space-3)">
              {SUMMARY_FIELDS.map(({ key, label }) => (
                <Stack key={key} direction="row" justify="space-between" gap="var(--jx-space-4)">
                  <Text tone="muted">{label}</Text>
                  <Text>{values[key] || '—'}</Text>
                </Stack>
              ))}
            </Stack>
          )}

          <Stack direction="row" justify="space-between" gap="var(--jx-space-3)">
            <Button
              type="button"
              variant="secondary"
              disabled={isFirst}
              onClick={() => setStep((prev) => prev - 1)}
            >
              Назад
            </Button>
            <Button type="submit" variant="primary">
              {isLast ? 'Отправить' : 'Дальше'}
            </Button>
          </Stack>
        </Stack>
      </form>
    </Card>
  );
}

